<?php require_once __DIR__.'/UnitPreferences.php'; $measurement=$item['measurement'];$names=array('weight'=>'Weight','body_composition'=>'Body composition','blood_pressure'=>'Blood pressure','spo2'=>'SpO2');$fields=array('weight'=>'Weight','body_fat'=>'Body fat','body_water'=>'Body water','bone_mass'=>'Bone mass','muscle_mass'=>'Muscle mass','bmi'=>'BMI','systolic'=>'Systolic','diastolic'=>'Diastolic','pulse'=>'Pulse','spo2'=>'SpO2','average'=>'Average','lowest'=>'Lowest','latest'=>'Latest','sleep_average'=>'Sleep average','next_sleep_average'=>'Next sleep average','seven_day_average'=>'Seven-day average');$roles=array('provider_report'=>'Provider summary','sample'=>'Recorded reading','hourly_average'=>'Hourly average','sleep_average'=>'Sleep average','calculated_mean'=>'Calculated mean'); ?>
<details class="calendar-entry type-measurement" <?php if(isset($_GET['day']))echo 'open'; ?>><summary><span class="entry-label">Private measurements</span><span class="entry-distance"><?php echo esc_html(count($measurement['reports'])+count($measurement['readings'])+count($measurement['aggregates'])+count($measurement['sleep_periods'])); ?> entries</span></summary><div class="entry-details"><p>Garmin · Private to you. Readings and provider averages are labeled separately. Dates follow the stored source calendar date; local times are shown only when recorded.</p>
<?php foreach(array('reports','readings','aggregates')as$bucket)foreach($measurement[$bucket]as$r): ?><section class="measurement-reading"><h4><?php echo esc_html(($names[$r['category']]??'Measurement').' · '.($roles[$r['role']]??'Recorded value')); ?></h4><?php if($r['time_local']): ?><p><?php echo esc_html(str_replace('T',' ',$r['time_local']).' (source local time)'); ?></p><?php elseif($r['time_utc']): ?><p><?php echo esc_html(str_replace('T',' ',$r['time_utc']).' (UTC; local time unavailable)'); ?></p><?php endif; ?><dl><?php foreach($r['values']as$key=>$v): ?><div><dt><?php echo esc_html($fields[$key]??$key); ?></dt><dd><?php echo esc_html(\SwimlogStandalone\UnitPreferences::measurementValue($key,$v['value'],$v['unit'],$owner)); ?></dd></div><?php endforeach; ?></dl><?php if($r['conflict']): ?><p>Conflicting source readings exist for this time; no value was silently chosen.</p><?php endif; ?></section><?php endforeach; ?>
<?php foreach($measurement['sleep_periods']as$r): ?><section class="measurement-reading"><h4>Hours slept</h4><p><?php echo esc_html(number_format_i18n($r['duration_seconds']/3600,2).' hours'); ?> · derived from verified UTC boundaries</p><p><?php echo esc_html('Bedtime: '.str_replace('T',' ',$r['start_local']?:$r['start_utc']).($r['start_local']?' (source local)':' (UTC)')); ?></p><p><?php echo esc_html('Wake time: '.str_replace('T',' ',$r['end_local']?:$r['end_utc']).($r['end_local']?' (source local)':' (UTC)')); ?></p></section><?php endforeach; ?></div></details>
